(()=>{const add=()=>{let app=document.querySelector("#app");if(!app)return;let brand=document.querySelector(".brand");if(brand&&!brand.dataset.enhanced){brand.dataset.enhanced="1";brand.innerHTML='<span class="brand-mark">↗</span><span class="brand-copy">Mi<span>Pasantia</span><small>EXPERIENCIAS REALES</small></span>'}let navPublish=document.querySelector('.nav [data-go="publicar"]');if(navPublish)navPublish.style.display="none";let hero=document.querySelector(".hero");if(hero)hero.dataset.enhanced="1";let pageTitle=document.querySelector(".page-title");if(pageTitle&&pageTitle.textContent.includes("Explorar")&&!document.querySelector(".explore-banner")){let banner=document.createElement("section");banner.className="explore-banner";banner.innerHTML='<h2>Encontrá una experiencia que te abra una puerta.</h2><p>Buscá por tema o combiná filtros para armar tu propio recorrido.</p><div class="quick-filters"><button data-qfilter="Tecnología">Tecnología</button><button data-qfilter="Diseño">Diseño</button><button data-qfilter="Administración">Administración</button><button data-qfilter="Salud">Salud</button></div>';pageTitle.closest(".section-head").after(banner)}let u=document.querySelector(".session-name");let route=location.hash.slice(1)||"inicio";if(u&&(route==="explorar"||route==="perfil")&&!document.querySelector(".fab-publish")){let fab=document.createElement("button");fab.className="fab-publish";fab.innerHTML='<span>＋</span><b class="fab-label">Compartir experiencia</b>';fab.onclick=()=>location.hash="publicar";document.body.append(fab)}};new MutationObserver(add).observe(document.body,{childList:true,subtree:true});document.addEventListener("click",e=>{let b=e.target.closest("[data-qfilter]");if(!b)return;let sel=document.querySelector("#cat");if(sel){sel.value=b.dataset.qfilter;sel.dispatchEvent(new Event("input",{bubbles:true}))}});add()})();
